function clearHistoryQuery(){const u=new URL(location.href);if(u.searchParams.has('history')){u.searchParams.delete('history');history.replaceState(history.state,'',u);}}
function openAcquisitions(){
 if(!state||acquisitionDialog.open)return;
 acquisitionEpoch++;acquisitionCursor=undefined;acquisitionBusy=false;acquisitionOwner=state.username;
 $('acquisitionRows').replaceChildren();$('acquisitionNotice').textContent='';$('acquisitionMore').hidden=true;
 acquisitionDialog.showModal();void loadAcquisitions();
}
async function loadAcquisitions(){
 if(!acquisitionDialog.open||acquisitionBusy||acquisitionCursor===null||acquisitionOwner!==state?.username)return;
 const epoch=acquisitionEpoch,cursor=acquisitionCursor;
 acquisitionBusy=true;$('acquisitionMore').disabled=true;$('acquisitionNotice').textContent='Kazanım geçmişi yükleniyor…';
 try{
  const result=await api('shop-history',cursor===undefined?{}:{cursor});
  if(epoch!==acquisitionEpoch||result.username!==acquisitionOwner||state?.username!==acquisitionOwner)return;
  for(const item of result.items){
   const li=make('li'),t=make('time',acquisitionDate.format(new Date(item.at)));t.dateTime=item.at;
   li.append(make('strong',item.name),make('span',sourceNames[item.source]||sourceNames.unknown),t);
   $('acquisitionRows').append(li);
  }
  acquisitionCursor=result.next;
  $('acquisitionNotice').textContent=$('acquisitionRows').children.length?'':'Henüz edinilmiş kozmetik yok.';
  $('acquisitionMore').hidden=!acquisitionCursor;$('acquisitionMore').textContent='Daha fazla göster';
 }catch(e){
  if(epoch!==acquisitionEpoch)return;
  $('acquisitionNotice').textContent=e.message;$('acquisitionMore').hidden=false;$('acquisitionMore').textContent='Tekrar dene';
 }finally{
  if(epoch===acquisitionEpoch){acquisitionBusy=false;$('acquisitionMore').disabled=false;}
 }
}
